{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_01fffa31fdf77ff3229a253f", "claim_ids": ["claim_40a16d11907bc954cf47c6b1", "claim_46af334c136f2b41f710b3a5"], "query_ids": ["q_321"], "claims": [{"claim_id": "claim_40a16d11907bc954cf47c6b1", "quote": "8708508000—DRIVE AXLES WITH DIFFERENTIAL FOR VEHICLES, NESOI", "url": "https://www.trade.gov/automotive-parts-tariff-codes", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"affected_product": "DRIVE AXLES WITH DIFFERENTIAL FOR VEHICLES, NESOI", "hts_code": "8708508000"}}, {"claim_id": "claim_46af334c136f2b41f710b3a5", "quote": "8708505000—DRIVE AXLES WITH DIFFERENTIAL FOR VEHICLES,OF 8703", "url": "https://www.trade.gov/automotive-parts-tariff-codes", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"affected_product": "DRIVE AXLES WITH DIFFERENTIAL FOR VEHICLES,OF 8703", "hts_code": "8708505000"}}]}, {"pair_id": "conflict_f333a9df68e6c2d800889d95", "claim_ids": ["claim_4e521fcea04f7c5b4cf86f39", "claim_d1b1ce5399e2d5ebd07c7759"], "query_ids": ["q_321"], "claims": [{"claim_id": "claim_4e521fcea04f7c5b4cf86f39", "quote": "8708506100—DRIVE AXLES WITH DIFFERENTIAL FOR VEHICLES, NESOI", "url": "https://www.trade.gov/automotive-parts-tariff-codes", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"affected_product": "DRIVE AXLES WITH DIFFERENTIAL FOR VEHICLES, NESOI", "hts_code": "8708506100"}}, {"claim_id": "claim_d1b1ce5399e2d5ebd07c7759", "quote": "8708500050—DRIVE AXLES WITH DIFFERNTL FOR VEHICLES,NESOI", "url": "https://www.trade.gov/automotive-parts-tariff-codes", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"affected_product": "DRIVE AXLES WITH DIFFERNTL FOR VEHICLES,NESOI", "hts_code": "8708500050"}}]}, {"pair_id": "conflict_4fcba7126590eb157a10061b", "claim_ids": ["claim_67ba12c8f253e2266425338e", "claim_80b5ddba3241f746c98b6b81"], "query_ids": ["q_321", "q_78"], "claims": [{"claim_id": "claim_67ba12c8f253e2266425338e", "quote": "- 8708504150 8708504150—NON-DRIVING AXLES AND PARTS FOR VEHICLES,NESOI", "url": "https://www.trade.gov/automotive-parts-tariff-codes", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"affected_product": "NON-DRIVING AXLES AND PARTS FOR VEHICLES,NESOI", "hts_code": "8708504150"}}, {"claim_id": "claim_80b5ddba3241f746c98b6b81", "quote": "8708504150—NON-DRIVING AXLES AND PARTS FOR VEHICLES,NESOI", "url": "https://www.trade.gov/automotive-parts-tariff-codes", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"affected_product": "NON-DRIVING AXLES AND PARTS FOR VEHICLES,NESOI", "hts_code": "8708504150"}}]}, {"pair_id": "conflict_69b5426445a54908fec769a8", "claim_ids": ["claim_bba87e1e5662b52499bb6320", "claim_dd981ea60fa2ba16855561fc"], "query_ids": ["q_321"], "claims": [{"claim_id": "claim_bba87e1e5662b52499bb6320", "quote": "- 8708500050 8708500050—DRIVE AXLES WITH DIFFERNTL FOR VEHICLES,NESOI", "url": "https://www.trade.gov/automotive-parts-tariff-codes", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"affected_product": "DRIVE AXLES WITH DIFFERNTL FOR VEHICLES,NESOI", "hts_code": "8708500050"}}, {"claim_id": "claim_dd981ea60fa2ba16855561fc", "quote": "8708507200—PARTS AND ACESSORIES FOR DRIVE AXLES", "url": "https://www.trade.gov/automotive-parts-tariff-codes", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"affected_product": "PARTS AND ACESSORIES FOR DRIVE AXLES", "hts_code": "8708507200"}}]}, {"pair_id": "conflict_507386b1ce8de044d7007c52", "claim_ids": ["claim_793120f4f8f8e22cad9bf0f9", "claim_fad18719610e432bed619e8c"], "query_ids": ["q_322"], "claims": [{"claim_id": "claim_793120f4f8f8e22cad9bf0f9", "quote": "the tariffs on automobile parts are set to go into effect on or after 12:01 a.m. eastern daylight time on May 3, 2025.", "url": "https://www.federalregister.gov/documents/2025/05/02/2025-07833/amendments-to-adjusting-imports-of-automobiles-and-automobile-parts-into-the-united-states", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"effective_date": "May 3, 2025"}}, {"claim_id": "claim_fad18719610e432bed619e8c", "quote": "The rules for importing auto parts into the US changed dramatically in May 2025, when a 25 percent Section 232 tariff hit engines, transmissions, powertrain components, and electrical parts — regardless of country of origin.", "url": "https://tglobeconsultants.com/importing-auto-parts-into-us", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232", "duty_rate": "25 percent", "effective_date": "May 3, 2025"}}]}, {"pair_id": "conflict_3b106938e6160c5b4969e8b8", "claim_ids": ["claim_85446b9a416b5ac882dd6b29", "claim_d796aa7ca1ac3dbce05c8cd9"], "query_ids": ["q_322"], "claims": [{"claim_id": "claim_85446b9a416b5ac882dd6b29", "quote": "The 25 percent tariff applies to auto parts for passenger vehicles and light trucks, specifically including: - Engines and engine parts - Transmissions - Powertrain components (driveshafts, axles, differentials) - Electrical components", "url": "https://tglobeconsultants.com/importing-auto-parts-into-us", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "25 percent"}}, {"claim_id": "claim_d796aa7ca1ac3dbce05c8cd9", "quote": "The real number for covered parts is 27.5 percent or higher.", "url": "https://tglobeconsultants.com/importing-auto-parts-into-us", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "27.5 percent or higher", "announcement_date": "2026"}}]}, {"pair_id": "conflict_31422776b11fe71fb7a0d7e5", "claim_ids": ["claim_85446b9a416b5ac882dd6b29", "claim_f3eeb833ec111cc07d16c2d1"], "query_ids": ["q_322"], "claims": [{"claim_id": "claim_85446b9a416b5ac882dd6b29", "quote": "The 25 percent tariff applies to auto parts for passenger vehicles and light trucks, specifically including: - Engines and engine parts - Transmissions - Powertrain components (driveshafts, axles, differentials) - Electrical components", "url": "https://tglobeconsultants.com/importing-auto-parts-into-us", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "25 percent"}}, {"claim_id": "claim_f3eeb833ec111cc07d16c2d1", "quote": "Base import duty on engines (HTS 8407) | $10,000 | 2.5% base rate on $400,000", "url": "https://tglobeconsultants.com/importing-auto-parts-into-us", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"hts_code": "8407", "duty_rate": "2.5%"}}]}, {"pair_id": "conflict_a7b50540b8464c35fbbbe6e3", "claim_ids": ["claim_12a48df233f67bf202e1a2ce", "claim_8c443534df6a79b7f627e704"], "query_ids": ["q_322"], "claims": [{"claim_id": "claim_12a48df233f67bf202e1a2ce", "quote": "Auto parts that qualify under the United States-Mexico-Canada Agreement (USMCA) get treated differently. During the transition period that began with the proclamation, USMCA-qualifying parts from Canada and Mexico remain tariff-free.", "url": "https://tglobeconsultants.com/importing-auto-parts-into-us", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "United States-Mexico-Canada Agreement (USMCA)", "duty_rate": "tariff-free"}}, {"claim_id": "claim_8c443534df6a79b7f627e704", "quote": "The agreement provides duty-free treatment for qualifying parts from Canada and Mexico, and during the current transition period it shields qualifying parts from the full Section 232 25 percent tariff.", "url": "https://tglobeconsultants.com/importing-auto-parts-into-us", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "USMCA", "duty_rate": "25 percent"}}]}, {"pair_id": "conflict_0959ab9efaf7c889062de9df", "claim_ids": ["claim_85446b9a416b5ac882dd6b29", "claim_e1687c3912ad6ae0ddf8b1b2"], "query_ids": ["q_322"], "claims": [{"claim_id": "claim_85446b9a416b5ac882dd6b29", "quote": "The 25 percent tariff applies to auto parts for passenger vehicles and light trucks, specifically including: - Engines and engine parts - Transmissions - Powertrain components (driveshafts, axles, differentials) - Electrical components", "url": "https://tglobeconsultants.com/importing-auto-parts-into-us", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "25 percent"}}, {"claim_id": "claim_e1687c3912ad6ae0ddf8b1b2", "quote": "The Section 232 proclamation includes a unique provision for USMCA-qualifying auto parts. Once the Commerce Department, in consultation with CBP, establishes the implementing process, the 25 percent tariff will apply only to the value of the non-US content of qualifying parts.", "url": "https://tglobeconsultants.com/importing-auto-parts-into-us", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232", "duty_rate": "25 percent"}}]}, {"pair_id": "conflict_35241e99b8cc0187595a3ae8", "claim_ids": ["claim_0b79b1d31aa3506dc4d14bf3", "claim_88c54c312cd7a8bd7c1574eb"], "query_ids": ["q_323"], "claims": [{"claim_id": "claim_0b79b1d31aa3506dc4d14bf3", "quote": "A 25% tariff took effect on April 3, 2025, for imported automobiles and light trucks, and on May 3, 2025, for specific auto parts such as engines, transmissions, and electrical components.", "url": "https://www.ghy.com/trade-compliance/us-to-apply-a-25-tariff-on-imports-of-autos-and-parts", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Proclamation 10908", "effective_date": "April 3, 2025"}}, {"claim_id": "claim_88c54c312cd7a8bd7c1574eb", "quote": "imposing a 25 percent ad valorem tariff on parts of passenger vehicles (sedans, sport utility vehicles, crossover utility vehicles, minivans, and cargo vans) and light trucks from all countries", "url": "https://content.govdelivery.com/accounts/USDHSCBP/bulletins/3de7ef9", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232", "duty_rate": "25 percent ad valorem", "effective_date": "May 3, 2025"}}]}]}

